"""Publish joint spectral/time event QC without making a new filter."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'docs/experiments/20261008-iphone-km184-public'
j=json.loads((OUT/'joint-event-timbre-qc.json').read_text())
embed=json.dumps({'summary':j['summary'],'events':j['events']},ensure_ascii=False,separators=(',',':'))
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>같은 탄현의 스펙트럼·시간 비교</title><style>:root{font-family:system-ui,-apple-system,sans-serif;color:#19333c;background:#f4f8f8}body{margin:0}main{max-width:1180px;margin:auto;padding:22px}a{color:#087d87}nav{display:flex;gap:14px;flex-wrap:wrap}h1{font-size:clamp(1.5rem,3vw,2.25rem)}p{line-height:1.55}.lead{background:#e8f3f1;border-left:5px solid #148a83;border-radius:7px;padding:15px}.layout{display:grid;grid-template-columns:180px minmax(0,1fr);gap:17px}.side{display:grid;align-content:start;gap:7px}button{font:inherit;border:1px solid #bdced2;background:white;border-radius:8px;padding:10px;cursor:pointer;text-align:left}button[aria-selected=true]{background:#087d87;color:white}.device{display:flex;gap:7px;flex-wrap:wrap}.panel{background:white;border:1px solid #d3e0e3;border-radius:9px;padding:14px;margin:12px 0}.bar-row{display:grid;grid-template-columns:105px 1fr 88px;gap:10px;align-items:center;margin:8px 0}.bar{position:relative;height:19px;background:#eff3f3;border-radius:3px}.bar:before{content:"";position:absolute;left:50%;top:0;bottom:0;border-left:1px solid #7d949b}.fill{position:absolute;height:13px;top:3px;border-radius:3px}.raw{background:#c87547}.eq{background:#158a9d}.metric{margin:18px 0}.small{font-size:.91rem;color:#526b74}.legend{display:flex;gap:16px;flex-wrap:wrap}.legend i{display:inline-block;width:12px;height:12px;margin-right:5px}.warning{border-left:4px solid #b88339;background:#fff7e9;padding:12px}@media(max-width:760px){.layout{grid-template-columns:1fr}.side{display:flex;overflow:auto}.side button{min-width:120px}}</style><main><nav><a href="temporal-spread-qc.html">퍼커션 시간 곡선</a><a href="attack-control.html">기존 후보 듣기</a><a href="october-four-device-eq.html">네 기기 비교</a></nav><h1>같은 탄현의 스펙트럼과 시간 변화</h1><p class="lead">단음 2개, 아르페지오 3개, 복합화음 3개, 퍼커션 2개를 기기별 국소 피크에 맞췄습니다. 처음 0–40ms, 다음 40–150ms, 뒤 150–300ms에서 <b>양쪽 녹음에서 실제 신호가 충분한 대역의 상대 크기와 스펙트럼 봉우리 대비</b>를 나란히 봅니다. ‘퍼진다’는 인상을 특정 원인으로 확정하지 않는 진단입니다.</p><div class="layout"><div class="side" id="groups"></div><section><div class="device" id="devices"></div><p id="description"></p><div class="legend"><span><i style="background:#c87547"></i>원본</span><span><i style="background:#158a9d"></i>기존 고정 EQ</span><span>가운데 0dB = KM184와 동일 · 10dB 이상 관측된 사건만 신뢰도 가중</span></div><div id="details"></div></section></div><p class="warning"><b>현재 판단:</b> 같은 보정이라도 주법과 시점에 따라 상위 성분의 부족·과다가 바뀝니다. 그러므로 배경 대비 신호가 부족한 대역을 제외한 뒤에도 이번에는 스펙트럼 후보나 감쇠 후보를 새로 선택하지 않았습니다. 단음에서의 개선을 복합화음과 퍼커션의 개선으로 간주할 수 없습니다. 뒤 150–300ms 값은 다음 아르페지오 음이나 낮은 신호대잡음비의 영향을 받을 수 있어 보조 자료입니다.</p><p class="small">출현 가중치의 감소 범위를 24·36·48dB로 바꿔도 대표 세 비교의 부족/과다 방향은 유지됐습니다. 이는 이 작은 자료에서의 방향 민감도 확인일 뿐입니다. <a href="joint-event-timbre-qc.json">민감도 원자료</a>.</p><p class="small">대역 비율: 1.6–3.2kHz 또는 3.2–6kHz의 평균 스펙트럼 파워 ÷ 0.8–1.6kHz. 봉우리 대비: 0.8–6kHz 로그 스펙트럼 파워의 90백분위−50백분위. 양수는 해당 지표가 KM184보다 크다는 뜻이며, 봉우리가 실제 배음인지 판정하지 않습니다. 각 주법당 2–3개 사건 중 두 녹음의 신호가 모두 배경 대비 10dB 이상인 대역만 사용하고, 관측 여유·대역 출현 강도로 가중한 평균이므로 낮은 가중치의 큰 차이는 보정 채택 근거가 아닙니다. 배경값은 같은 10월 세션의 조용한 구간에서 얻은 대리치이며 실제 마이크 자체 잡음이 아닙니다. 일반화·청감 인과·독립 검증 결과가 아닙니다. <a href="joint-event-timbre-qc.json">사건별 원자료·정렬 방법</a>.</p></main><script>const D=__DATA__,gs=[['open_notes','단음'],['arpeggio','아르페지오'],['complex','복합화음'],['percussion','퍼커션']],ds=['iphone','s21','h1','d10'],stage=[['attack','어택 0–40ms'],['body','본체 40–150ms'],['tail','후기 150–300ms']],metrics=[['upper_16_32_over_08_16_db','1.6–3.2kHz / 0.8–1.6kHz'],['upper_32_60_over_08_16_db','3.2–6kHz / 0.8–1.6kHz'],['peak_background_contrast_db','스펙트럼 봉우리 / 주변 대비']];let group='arpeggio',device='iphone';const fmt=v=>v===null?'—':(v>=0?'+':'')+v.toFixed(2)+'dB';function bar(v,color){if(v===null)return '<div class="bar" style="background:#e3e9eb;text-align:center;font-size:12px">근거 부족</div>'; let w=Math.min(Math.abs(v),14)/28*100,left=v<0?50-w:50;return `<div class="bar"><span class="fill ${color}" style="left:${left}%;width:${w}%"></span></div>`}function render(){document.querySelectorAll('#groups button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.group===group)));document.querySelectorAll('#devices button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.device===device)));let count=D.events.filter(e=>e.group===group).length;document.getElementById('description').textContent=gs.find(x=>x[0]===group)[1]+' · '+device.toUpperCase()+' · '+count+'개 사건 관측·출현 가중 평균 · 기기−KM184 (dB)';let q=D.summary[group][device],html='';for(let [key,title] of stage){html+=`<div class="panel"><h2>${title}</h2>`;for(let [m,label] of metrics){let raw=q.raw[key][m].confidence_weighted_mean_db,eq=q.fixed_eq?.[key]?.[m]?.confidence_weighted_mean_db;html+=`<div class="metric"><strong>${label}</strong><div class="bar-row"><span>원본</span>${bar(raw,'raw')}<b>${fmt(raw)}</b></div>`;if(eq!==undefined)html+=`<div class="bar-row"><span>기존 EQ</span>${bar(eq,'eq')}<b>${fmt(eq)}</b></div>`;html+=`<small>사용 가능한 사건 ${q.raw[key][m].valid_events}/${count} · 관측·출현 가중치 ${q.raw[key][m].mean_confidence.toFixed(2)}${q.raw[key][m].mean_confidence<.35?' (낮음)':''} · 두 버전에 동일한 마스크</small></div>`}html+='</div>'}document.getElementById('details').innerHTML=html}document.getElementById('groups').innerHTML=gs.map(([k,n])=>`<button data-group="${k}">${n}</button>`).join('');document.getElementById('devices').innerHTML=ds.map(k=>`<button data-device="${k}">${k.toUpperCase()}</button>`).join('');document.querySelectorAll('#groups button').forEach(b=>b.onclick=()=>{group=b.dataset.group;render()});document.querySelectorAll('#devices button').forEach(b=>b.onclick=()=>{device=b.dataset.device;render()});render()</script></html>'''.replace('__DATA__',embed)
(OUT/'joint-event-timbre-qc.html').write_text(page)
print(OUT/'joint-event-timbre-qc.html')
